const TXM={ok:'数式：MathJax 3.2.2 で表示',fail:'数式：MathJax を読み込めないため TeX のソースを表示',load:'数式：MathJax を読み込み中（TeX のソースを表示）'};
function txStat(){const e=$('txs');if(e)e.textContent=TXM[MJX.st]||TXM.load}
function txRaw(el){el.textContent=el.dataset.tex;el.classList.add('raw');el.classList.remove('mj')}
function txMJ(el){const n=MathJax.tex2svg(el.dataset.tex,{display:el.dataset.d==='1'});el.replaceChildren(n);el.classList.add('mj');el.classList.remove('raw');if(!MJX.gc){const g=MathJax.startup.output.fontCache.getCache();if(g){g.style.position='absolute';g.style.width=g.style.height='0';document.body.appendChild(g);MJX.gc=1}}} /* 字形の定義は 1 か所（global cache）に置き，各式は参照だけにする */
function txFail(){if(MJX.st!=='load')return;MJX.st='fail';MJX.q.length=0;txStat()}
function txLoad(){if(MJX.st!=='idle')return;MJX.st='load';txStat();
 window.MathJax={tex:{inlineMath:[],displayMath:[]},svg:{fontCache:'global'},options:{enableMenu:false,enableAssistiveMml:false},startup:{typeset:false,ready(){MathJax.startup.defaultReady();MathJax.startup.promise.then(()=>{if(MJX.st!=='load')return;MJX.st='ok';document.head.appendChild(MathJax.svgStylesheet());txStat();txAll()})}}};
 const sc=document.createElement('script');sc.src=MJX.url;sc.async=true;sc.dataset.mj='1';sc.onerror=txFail;document.head.appendChild(sc);setTimeout(txFail,MJX.wait)}
/* 画面に入る数式（表示範囲と上下 1 画面分）だけを組む．組んだ式は戻さない（全式を組むと要素が多すぎてタブの切替が重くなる） */
function txAll(){if(MJX.st!=='ok')return;if(!MJX.io)MJX.io=new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){MJX.io.unobserve(e.target);if(!e.target.classList.contains('mj'))MJX.q.push(e.target)}if(MJX.q.length&&!MJX.run){MJX.run=1;requestAnimationFrame(txPump)}},{root:$('s4'),rootMargin:'100% 0px'});
 for(let k=0;k<DOCK.length;k++)if(DV.built[k]===1)for(const e of $('dv'+k).querySelectorAll('.tx:not(.mj):not([data-io])')){e.dataset.io='1';MJX.io.observe(e)}}
function txPump(){if(MJX.st!=='ok'){MJX.run=0;return}const t0=performance.now();while(MJX.q.length&&performance.now()-t0<8){const e=MJX.q.shift();if(e.isConnected&&!e.classList.contains('mj'))txMJ(e)}if(MJX.q.length)requestAnimationFrame(txPump);else{MJX.run=0;docFit(DV.cur)}}
/* 式の解説は，初めて開いたときに章を数フレームに分けて表示する（初回の組版を 1 フレームに集めない） */
function docReveal(){if(DV.rev||!DV.pend.length)return;DV.rev=1;const go=()=>{if(U.tab!==4||DV.cur!==0){DV.rev=0;return}const E=$('dv0'),t0=performance.now();while(DV.pend.length&&performance.now()-t0<8){DV.pend.shift().style.display='';void E.offsetHeight};if(DV.pend.length)requestAnimationFrame(go);else DV.rev=0};go()}
function fitMath(root){root.querySelectorAll('.mx').forEach(dv=>{const m=dv.firstElementChild;if(m)m.style.fontSize=''})}
function buildToc(){const t=$('toc');t.innerHTML='<b>目次</b>'+[...$('s4').querySelectorAll('h3[data-sec]')].map(h=>`<a data-go="${h.dataset.sec}">${h.textContent}</a>`).join('')}
const docTo=h=>{const S=$('s4');if(h)S.scrollTop+=h.getBoundingClientRect().top-S.getBoundingClientRect().top};
function docGo(n){docTo($('s4').querySelector(`h3[data-sec="${n}"]`))}
/* ===== 文書の閲覧（要件定義書・仕様書・用語の定義集．ビルド時に HTML へ変換し，数式は TeX のまま埋め込んである） ===== */
const DOCK=['','req','spec','gui','glo'],DOCS=(()=>{try{return JSON.parse(document.getElementById('docdata').textContent)}catch(e){return{}}})(),DV={built:[1,0,0,0,0],top:[0,0,0,0,0],pg:[0,0,0,0,0],ix:[{},{},{},{},{}],cur:0,pend:[],rev:0};
/* 4 文書（要件定義書，仕様書，画面の文書，用語の定義集）は見出しごとの断片を 1 ページとして，表示中のページだけを画面に置く（SPEC-16 の 9） */
function docBuild(k){const q=DOCS[DOCK[k]],el=$('dv'+k);if(DV.built[k]||!q)return;const nav=`<div class="dnav"><button data-pg="-1" data-k="${k}">◀ 前</button><span class="dn"></span><button data-pg="1" data-k="${k}">次 ▶</button></div>`;
 el.innerHTML=`<button class="tocb" data-tocb="${k}">目次（${q.toc.length} 項目）を開く</button><div class="toc dtoc" id="dt${k}" style="display:none">${q.toc.map(t=>`<a data-h="${t[1]}" data-k="${k}" class="l${t[0]}">${t[2].replace(/&/g,'&amp;').replace(/</g,'&lt;')}</a>`).join('')}</div>${nav}<div class="dpg"></div>${nav}`;
 q.chunks.forEach((c,i)=>{const m=/^\s*<h[23] id="([^"]+)"/.exec(c);if(m)DV.ix[k][m[1]]=i});DV.built[k]=1;docPage(k,DV.pg[k])}
function docPage(k,i){const q=DOCS[DOCK[k]],el=$('dv'+k);if(!q)return;if(!DV.built[k]){DV.pg[k]=i;docBuild(k);return}const n=q.chunks.length;i=Math.max(0,Math.min(n-1,i));DV.pg[k]=i;el.querySelector('.dpg').innerHTML=q.chunks[i];xrRows(el.querySelector('.dpg'));
 for(const nv of el.querySelectorAll('.dnav')){const b=nv.querySelectorAll('button');b[0].disabled=i===0;b[1].disabled=i===n-1;nv.querySelector('.dn').textContent=`${i+1} / ${n}`}docFit(k);txAll()}
/* 相互参照（SPEC-16 の 10）：REQ-nn，SPEC-nn，TEST-nn の見出しと式の解説の章（data-req）を行き先にし，リンクで移る．移る前の位置は履歴（最大 20 件）に積み，[◀ 戻る] で戻る */
const XR={t:null,sec:null,hist:[]};
function xrMap(){if(XR.t)return;XR.t={};for(let k=1;k<DOCK.length;k++){const q=DOCS[DOCK[k]];if(q)for(const t of q.toc){const m=/^((?:REQ|SPEC|TEST)-\d\d)：/.exec(t[2]);if(m&&!XR.t[m[1]])XR.t[m[1]]={k,id:t[1]}}}XR.sec={};$('dv0').querySelectorAll('h3[data-req]').forEach(h=>h.dataset.req.split(',').forEach(r=>(XR.sec[r]=XR.sec[r]||[]).push(h.dataset.sec)))}
const xrA=(x,l)=>`<a class="xr" data-x="${x}">${l||x}</a>`;
/* 対応の行：見出しの種類（skip）を除いた同じ番号の REQ，SPEC，TEST と，式の解説の章．式の解説の章の行（skip が空）には章を入れない */
function xrRow(ns,skip){xrMap();const a=[];for(const n of ns){for(const q of['REQ','SPEC','TEST'])if(q!==skip&&XR.t[q+'-'+n])a.push(xrA(q+'-'+n));if(skip)for(const c of XR.sec[n]||[])a.push(xrA('§'+c,'式 §'+c))}return`<p class="xrow"><span>対応</span>${a.join('')}</p>`}
function xrRows(root){for(const h of root.querySelectorAll('h2,h3')){const m=/^(REQ|SPEC|TEST)-(\d\d)：/.exec(h.textContent);if(m&&!(h.nextElementSibling&&h.nextElementSibling.classList.contains('xrow')))h.insertAdjacentHTML('afterend',xrRow([m[2]],m[1]))}}
/* 式の解説の本文中の表記をリンクにする（4 文書はビルド時に同じ規則でリンクにしてある） */
function xrText(root){const re=/(?<![A-Za-z0-9])((?:REQ|SPEC|TEST)-(?:0[1-9]|[12][0-9]|3[0-5]))(?![0-9])/g,w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('h1,h2,h3,h4,code,pre,.tx,.im,.dx,a')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}),ns=[];while(w.nextNode())ns.push(w.currentNode);for(const n of ns){const t=n.nodeValue;re.lastIndex=0;if(!re.test(t))continue;const f=document.createElement('span');f.innerHTML=t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(re,q=>xrA(q));n.replaceWith(...f.childNodes)}}
function xrGo(x){xrMap();const S=$('s4'),sec=x[0]==='§',t=sec?null:XR.t[x];if(!sec&&!t)return;XR.hist.push({k:DV.cur,pg:DV.pg[DV.cur],top:S.scrollTop});if(XR.hist.length>20)XR.hist.shift();
 if(sec){while(DV.pend.length)DV.pend.shift().style.display='';docShow(0);docGo(+x.slice(1))}else{docShow(t.k);const i=DV.ix[t.k][t.id];if(i!=null&&i!==DV.pg[t.k])docPage(t.k,i);docTo(document.getElementById(t.id))}xrBk()}
function xrBack(){const h=XR.hist.pop();if(!h)return;docShow(h.k);if(h.k&&DV.pg[h.k]!==h.pg)docPage(h.k,h.pg);$('s4').scrollTop=h.top;xrBk()}
function xrBk(){const b=$('dback');if(b)b.style.display=XR.hist.length?'':'none'}
/* 行に収まらない本文中の数式を，その式だけ横スクロールできる行にする */
function docFit(k){const el=$('dv'+k);if(U.tab!==4||DV.built[k]!==1||!el.clientWidth)return; /* 解説タブを隠している間は測らない（隠した内容の寸法を読むと，レイアウトをやり直すことになる） */const ims=[...el.querySelectorAll('.im')].filter(s=>!s.closest('.tw')),w=ims.map(s=>{const b=s.closest('p,li,td,div'),c=s.firstElementChild;return[c?c.getBoundingClientRect().width:0,b?b.clientWidth:el.clientWidth]});ims.forEach((s,i)=>s.classList.toggle('w',w[i][0]>w[i][1]-1))}
function docShow(k){const S=$('s4');DV.top[DV.cur]=S.scrollTop;DV.cur=k;for(let j=0;j<DOCK.length;j++)$('dv'+j).classList.toggle('off',j!==k);[...$('dsw').children].forEach((b,j)=>b.className=j===k?'on':'');if(k){docBuild(k);docFit(k)}else docReveal();S.scrollTop=DV.top[k]}
function docTap(e){const xa=e.target.closest('a.xr');if(xa){xrGo(xa.dataset.x);return}const b=e.target.closest('[data-tocb]');if(b){const t=$('dt'+b.dataset.tocb),op=t.style.display==='none';t.style.display=op?'':'none';b.textContent=`目次（${DOCS[DOCK[+b.dataset.tocb]].toc.length} 項目）を${op?'閉じる':'開く'}`;return}const g=e.target.closest('button[data-pg]');if(g&&!g.disabled){const k=+g.dataset.k,el=$('dv'+k);docPage(k,DV.pg[k]+(+g.dataset.pg));docTo(el.querySelector('.dnav'));return}const a=e.target.closest('a[data-h]');if(a){const k=+a.dataset.k,ix=DV.ix[k][a.dataset.h];if(ix!=null&&ix!==DV.pg[k])docPage(k,ix);docTo(document.getElementById(a.dataset.h))}}
function inlineMath(root){const re=/(?<![A-Za-z])((?:[A-Za-zα-ωΑ-Ω][\u0304\u0307]?|ṁ)_[A-Za-z0-9α-ω]+|N̄|ṁ)/gu,w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('.tx,a,.src,th')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}),ns=[];while(w.nextNode())ns.push(w.currentNode);for(const n of ns){const t=n.nodeValue.normalize('NFC');if(!re.test(t))continue;re.lastIndex=0;const f=document.createElement('span');f.innerHTML=t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(re,q=>Mi(q));n.replaceWith(...f.childNodes)}}
function docVals(){document.querySelectorAll('#s4 [data-v]').forEach(e=>{const it=IT[e.dataset.v];e.textContent=disp(it,LP[it.k])});document.querySelectorAll('#s4 [data-opt]').forEach(e=>e.classList.toggle('cur',String(LP[e.dataset.opt])===e.dataset.val))}
